contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address account, uint256 amount) public {
        // Precondition: the account has no pre-position yet and no position.
        require(!c.isLiquidating(account));

        uint256 beforeOracleVersion = c.latestVersion();
        PrePosition memory before = c.pre(account);
        require(before.openPosition.maker == 0 && before.openPosition.taker == 0 && before.closePosition.maker == 0 && before.closePosition.taker == 0);

        // Open a maker position for the account.
        c.openMakeFor(account, UFixed18.wrap(amount));

        PrePosition memory after = c.pre(account);

        // The open-maker pre-position must record exactly the requested amount,
        // and the account must not end up with a double-sided position.
        Position memory p = c.position(account);
        assert(after.openPosition.maker == UFixed18.wrap(amount) && p.maker == 0);
    }
}

