contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint128 oracleVersion) public {
        // Parameter precondition: test a strictly positive take amount.
        require(amount > 0);

        // Snapshot the account's position before opening the take position.
        Position memory before = c.position(address(this));

        // Make the call whose effect we are asserting on.
        c.openTake(UFixed18.wrap(amount));

        // Read the post-call position.
        Position memory after_ = c.position(address(this));

        // General rule: a take open increases the taker position by exactly the requested
        // amount and does not change the account's maker position.
        assert(
            UFixed18.unwrap(after_.taker) == UFixed18.unwrap(before.taker) + amount &&
            UFixed18.unwrap(after_.maker) == UFixed18.unwrap(before.maker)
        );
    }
}

