        bool beforeClosed = c.closed();

        bool updateReverted;
        try c.updateClosed(newClosed) { updateReverted = false; } catch { updateReverted = true; }

        bool afterClosed = c.closed();

        // updateClosed must succeed (it is onlyProductOwner and this test is the deployer/owner).
        assert(!updateReverted);

