        if (afterClosed) {
            bool openMakeReverted;
            try c.openMake(1) { openMakeReverted = false; } catch { openMakeReverted = true; }
            assert(openMakeReverted);

            bool openTakeReverted;
            try c.openTake(1) { openTakeReverted = false; } catch { openTakeReverted = true; }
            assert(openTakeReverted);
        }
    }
