contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount) public payable {
        // account must not be the zero address? not needed; c handles it
        // Only test with a possibly nonzero amount
        require(amount > 0, "amount must be > 0");

        // Read the maker position before
        Position memory beforePos = c.position(account);
        uint256 beforeMaker = UFixed18.unwrap(beforePos.maker);

        // Call openMakeFor -- this changes state
        // It may revert; if it does, the assertion must hold trivially? The rule is about success.
        bool reverted;
        try c.openMakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If it succeeded, the account's maker position should be beforeMaker + amount
        if (!reverted) {
            Position memory afterPos = c.position(account);
            uint256 afterMaker = UFixed18.unwrap(afterPos.maker);
            assert(afterMaker == beforeMaker + amount || afterPos.maker.gt(UFixed18Lib.ZERO) == false);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

